using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer.Tools;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The SDK creates a transient instance per tool invocation, resolving
/// constructor parameters from the DI container automatically.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;
    private static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true };

    // HttpClient is injected by the DI container via IHttpClientFactory's named client.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool(Name = "get_current_weather")]
    [Description("Gets the current weather for a city using the wttr.in API.")]
    public async Task<string> GetCurrentWeatherAsync(
        [Description("City name, e.g. 'Seattle' or 'London'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _http.GetAsync($"/{Uri.EscapeDataString(city)}?format=j1", cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var current = doc.RootElement.GetProperty("current_condition")[0];

        var tempC = current.GetProperty("temp_C").GetString();
        var humidity = current.GetProperty("humidity").GetString();
        var desc = current.GetProperty("weatherDesc")[0].GetProperty("value").GetString();

        return $"Weather in {city}: {desc}, {tempC}°C, humidity {humidity}%";
    }

    [McpServerTool(Name = "get_forecast")]
    [Description("Gets a 3-day weather forecast for a city using the wttr.in API.")]
    public async Task<string> GetForecastAsync(
        [Description("City name, e.g. 'Tokyo' or 'Paris'")] string city,
        [Description("Number of forecast days (1-3). Defaults to 3.")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);

        var response = await _http.GetAsync($"/{Uri.EscapeDataString(city)}?format=j1", cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var forecasts = doc.RootElement.GetProperty("weather");
        var lines = new List<string> { $"Forecast for {city}:" };

        for (int i = 0; i < Math.Min(days, forecasts.GetArrayLength()); i++)
        {
            var day = forecasts[i];
            var date = day.GetProperty("date").GetString();
            var maxC = day.GetProperty("maxtempC").GetString();
            var minC = day.GetProperty("mintempC").GetString();
            lines.Add($"  {date}: {minC}°C – {maxC}°C");
        }

        return string.Join("\n", lines);
    }
}

